-- Class notes synopsis batch 21: Psyllium through Rhubarb

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Psyllium</strong> husk/seed is a <strong>bulking laxative</strong> and water-soluble fiber that feeds the <strong>microbiome</strong>; "fill and scrape." For <strong>deficient/laxative-dependent constipation</strong> and cardiovascular health support. Psyllium seed in bulk-building candy for <strong>childhood constipation</strong> (with <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=76"><strong>Fennel</strong></a>, <a href="?herb=45"><strong>Marshmallow</strong></a> root, and dried fruit). <strong>Requires plenty of water - lack of water causes issues; only use if drinking a lot of water with it. Can become reliant on psyllium; not intended for lifelong use - aim for natural peristaltic urge. Ok to shift patterns, but not a permanent strategy.</strong>$$
WHERE id = 2240;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Pumpkin</strong> seeds are a food source of <strong>zinc</strong>; beneficial for <strong>sperm health</strong>; zinc depleted through semen expression - pumpkin seeds as food source for replenishment. Pumpkin seed oil in BPH herbal formula. Diet for <strong>erectile dysfunction</strong>: zinc from pumpkin seeds; avoid processed food, refined grains, alcohol, sugar, and caffeine.$$
