UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Raspberry</strong> (Red Raspberry leaf; Rubus spp.) is a <strong>uterine tonic</strong>, <strong>astringent</strong> (tannin-rich constricting herb), and deeply <strong>nutritive</strong> mineral-rich herb - one of the classic mineral-rich infusion herbs; nutrient-rich tea, alkalizing to the gut; rich in vitamins A, C, E and minerals Ca, Fe, K, Zn. Tea extracts minerals; alcohol does not; work with consistently over time, best taken all cycle long rather than just acutely. For the <strong>uterus</strong>: tonifying and nourishing; for <strong>heavy bleeding</strong> in teens alongside <a href="?herb=43"><strong>Nettle</strong></a>; for <strong>fibroids causing heavy bleeding</strong> - reduces tonic contractions of the uterus, hemostatic when capillaries won't close down; for <strong>amenorrhea</strong> (tone while nourishing); used when uterus hasn't returned to pre-pregnancy tone after multiple pregnancies; uterine tonic after pregnancy loss; in tincture for hormone and uterine support; for <strong>menstrual cramps</strong> alone or with <a href="?herb=43"><strong>Nettle</strong></a>. Astringent for <strong>diarrhea</strong> (Rubus spp. / raspberry root) alongside <a href="?herb=44"><strong>Yarrow</strong></a> and <a href="?herb=75"><strong>Meadowsweet</strong></a>; <strong>Upper GI excess</strong>: astringent. Nutritional tea for <strong>fertility</strong> - complement with moistening herbs like <a href="?herb=70"><strong>Calendula</strong></a> if needed. For mineral-depleted states: combine with <a href="?herb=2287"><strong>Oat Straw</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, and <a href="?herb=134"><strong>Lemon Balm</strong></a>. Ingredient (2 T) in Iron Tonic Syrup for pregnancy. For <strong>anemia in pregnancy</strong>; in cold infusion tea for mineral extraction; can be swapped with <a href="?herb=151"><strong>Horsetail</strong></a> for better diaphoretic action or to alleviate nighttime urination. Liver excess: mineral-rich herb to buffer blood. For dry constitution: moistening. <strong>Very drying - avoid in first trimester (first 3 months). After first trimester: very nourishing and can prepare uterus for the birth process. Avoid if miscarriage concerns - astringency can tighten the uterus.</strong>$$
WHERE id = 155;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Red Clover</strong> (Trifolium pratense) is a <strong>phytoestrogenic</strong>, <strong>alterative</strong>, <strong>blood cleanser</strong>, <strong>lymphatic</strong>, <strong>bile-stimulating</strong>, and deeply <strong>nutritive</strong> mineral-rich herb; salty taste; nutrient-rich tea, alkalizing to the gut; high in vitamins B1, B2, B6, inositol, and Vitamin C; "little bit, not too much." Phyto-estrogenic mechanism: if estrogen receptors are full, Red Clover (weaker estrogen) steals receptors and decreases net estrogenic effect; if receptors are empty (low estrogen), it fills them and increases effect. For <strong>bone density</strong> in post-menopause; for <strong>fibroids</strong>: blood mover for stasis, isoflavones enhance progesterone; encourages <strong>apoptosis</strong> for fibrosis/fibroblast accumulation. For <strong>fertility</strong>: nutritional tea (Legume Tea to Support Fertility - suggest both partners drink); complement with moistening herbs if needed. Inositol-rich tea blend for <strong>PMOS</strong>: <a href="?herb=225"><strong>Astragalus</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, Red Clover, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=1547"><strong>Kudzu Root</strong></a>. Hormone support formula (2 tsp 3x/day): <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=2238"><strong>White Peony</strong></a>, Red Clover, <a href="?herb=190"><strong>Chasteberry</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>. Mineral-rich stress-depletion formula alongside <a href="?herb=155"><strong>Raspberry</strong></a> leaf, <a href="?herb=2287"><strong>Oat Straw</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>. In nourishing infusion with <a href="?herb=885"><strong>Alfalfa</strong></a> for thyroid/Hashimoto's case. Hepatic support for elimination and detox alongside <a href="?herb=17"><strong>Schizandra</strong></a>, <a href="?herb=206"><strong>Milk Thistle</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=28"><strong>Cleavers</strong></a>, <a href="?herb=37"><strong>Yellow Dock</strong></a>; bile-stimulating in hepatic/alterative protocol for chemical sensitivity and detox. Regenerative tea blend (large daily infusions): <a href="?herb=151"><strong>Horsetail</strong></a>, <a href="?herb=95"><strong>Corn Silk</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=1014"><strong>Lady's Mantle</strong></a>, <a href="?herb=2233"><strong>Hibiscus</strong></a>, Red Clover. Liver excess: mineral-rich herb to buffer blood alongside <a href="?herb=155"><strong>Raspberry</strong></a> leaf, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>. Blood-cleanse tradition for <strong>skin conditions</strong> (eczema) and menopausal symptom support; alterative especially for the elderly; GI alterative. Prevention-oriented for miscarriage-prone individuals; blood mover for stagnation (tendency toward clots). Hot water infusion necessary to break cell walls. <strong>Significant phytoestrogen capacity - avoid in hyperestrogenic conditions (ovarian cancer, estrogen-responsive cancers, endometrial hyperplasia, endometriosis, fibroids).</strong>$$
WHERE id = 42;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Red Root</strong> (Ceanothus) is a powerful <strong>lymphagogue</strong>, <strong>astringent</strong>, and <strong>circulatory stimulant</strong> - master lymph mover, whole body; foamy tincture, very tannin-y; saponins in flowers and root; energetically moving. Midsection lymphatic affinity (alongside <a href="?herb=39"><strong>Figwort</strong></a> as general lymphatic and <a href="?herb=28"><strong>Cleavers</strong></a> for neck/throat). Drying lymphatic - specifically indicated for <strong>water retention</strong> and <strong>lymphatic congestion</strong>; powerful but drying - dose: MM range 30-90 drops, Tilgner range 20-40 drops. Can thin the blood (high hemoglobin, high serum, blood lipids); if the root is red, it is medicinal. Getting Sick Blend: <a href="?herb=26"><strong>Echinacea</strong></a>, <a href="?herb=2229"><strong>Gotu Kola</strong></a>, Red Root, <a href="?herb=1651"><strong>Elder</strong></a> berry glycerite. For <strong>long COVID</strong>: lymphatic clearance in chronic pain from stealth viral infections (Buehner protocol). Paired with <a href="?herb=35"><strong>Poke Root</strong></a> for fibrocystic acute <strong>breast disease</strong>; for acute <strong>mastitis</strong> with <a href="?herb=35"><strong>Poke Root</strong></a> and <a href="?herb=2635"><strong>Cotton Root Bark</strong></a>. Wound wash astringent alongside <a href="?herb=44"><strong>Yarrow</strong></a>; astringent for <strong>Hot Damp Diarrhea</strong>. Lymph circulation for <strong>rheumatoid arthritis</strong>. For <strong>common cold</strong> and <strong>influenza</strong>: lymphatic support. Lymph alterative for hot constitution alongside <a href="?herb=28"><strong>Cleavers</strong></a> and <a href="?herb=70"><strong>Calendula</strong></a>. Circulatory stimulant for wet constitution. Lymph/Immune deficiency lymphagogue alongside <a href="?herb=309"><strong>Yerba Mansa</strong></a>, <a href="?herb=1248"><strong>Ocotillo</strong></a>, <a href="?herb=35"><strong>Poke Root</strong></a>, <a href="?herb=41"><strong>Queen's Delight</strong></a>.$$
WHERE id = 981;

